#include "../src/memory_audit.hpp"
#include <cassert>
#include <cstring>
#include <iostream>
int main(){using namespace memory_audit;Events e;Point p;p.workingKB=44000;p.commitKB=30000;p.modules=60;e.push(Event::DiagnosticsBefore,p);p.gdi=52;p.user=41;e.push(Event::DiagnosticsOpened,p);e.push(Event::QuickBefore,p);p.workingKB=70000;p.commitKB=39000;p.modules=115;e.push(Event::QuickReady,p);e.push(Event::QuickWritten,p);e.push(Event::QuickWritten,p);e.push(Event::NoticeClosed,p);p.user=30;e.push(Event::DiagnosticsClosed,p);assert(e.count==8&&e.at(0).sequence==1&&e.at(7).sequence==8);assert(e.at(3).memory.workingKB==70000&&e.at(0).memory.modules==60);assert(e.at(7).event==Event::DiagnosticsClosed);for(unsigned i=0;i<100;++i){p.builds=i;e.push(Event::QuickFailed,p);}assert(e.count==32&&e.at(0).sequence==77&&e.at(31).sequence==108);for(auto type:{Event::DiagnosticsBefore,Event::DiagnosticsOpened,Event::DiagnosticsClosed,Event::QuickBefore,Event::QuickReady,Event::QuickWritten,Event::QuickFailed,Event::QuickWritten,Event::QuickFailed,Event::NoticeClosed})assert(std::strcmp(eventName(type),"Unknown")!=0);std::cout<<"PASS: bounded UI event history, quick-export event ordering, snapshot preservation, module counts, cancel/failure labels and ring eviction.\n";}
